INSERT INTO units(id,tenant_id,project_id,code,layout,floor_label,floor_number,area_m2,usable_area_m2,balcony_m2,terrace_m2,garden_m2,commercial_status)
SELECT source_id,'{{TENANT_ID}}',(SELECT id FROM dej_project),code,layout,floor_label,floor,area,usable,balcony,terrace,garden,COALESCE(('{"206":"reserved","312":"pre_reserved","314":"reserved"}'::jsonb->>code),'available')
FROM dej_units_source
ON CONFLICT (tenant_id,project_id,(lower(code))) WHERE archived_at IS NULL DO UPDATE SET layout=EXCLUDED.layout,floor_label=EXCLUDED.floor_label,floor_number=EXCLUDED.floor_number,area_m2=EXCLUDED.area_m2,usable_area_m2=EXCLUDED.usable_area_m2,balcony_m2=EXCLUDED.balcony_m2,terrace_m2=EXCLUDED.terrace_m2,garden_m2=EXCLUDED.garden_m2,updated_at=now();
UPDATE units SET archived_at=now() WHERE tenant_id='{{TENANT_ID}}' AND project_id=(SELECT id FROM dej_project) AND archived_at IS NULL AND code NOT IN (SELECT code FROM dej_units_source);
CREATE TEMP TABLE dej_unit_map ON COMMIT DROP AS SELECT source.code,unit.id FROM dej_units_source source JOIN units unit ON unit.tenant_id='{{TENANT_ID}}' AND unit.project_id=(SELECT id FROM dej_project) AND lower(unit.code)=lower(source.code) AND unit.archived_at IS NULL;
INSERT INTO unit_commercial_status_events(id,tenant_id,project_id,unit_id,from_status,to_status,command,reason,recorded_by_membership_id,effective_at)
SELECT ('de210000-0000-4000-8000-'||lpad(row_number() OVER (ORDER BY unit.code)::text,12,'0'))::uuid,'{{TENANT_ID}}',(SELECT id FROM dej_project),unit.id,NULL,unit.commercial_status,'seed','První známý stav při pilotním importu','{{IMPORTER_MEMBERSHIP_ID}}','2026-07-21T00:00:00+02:00'
FROM units unit WHERE unit.tenant_id='{{TENANT_ID}}' AND unit.project_id=(SELECT id FROM dej_project) AND unit.archived_at IS NULL
ON CONFLICT(id) DO NOTHING;

