INSERT INTO accessories(id,tenant_id,project_id,accessory_type_id,code,area_m2,floor_label)
SELECT source_id,'{{TENANT_ID}}',(SELECT id FROM dej_project),type.id,source.code,source.area,source.floor
FROM dej_accessories_source source JOIN accessory_types type ON type.tenant_id='{{TENANT_ID}}' AND type.code=CASE WHEN source.code LIKE 'S%' THEN 'cellar' ELSE 'parking' END
ON CONFLICT (tenant_id,project_id,(lower(code))) WHERE archived_at IS NULL DO UPDATE SET area_m2=EXCLUDED.area_m2,floor_label=EXCLUDED.floor_label,updated_at=now();
UPDATE accessories SET operational_status='archived',archived_at=now() WHERE tenant_id='{{TENANT_ID}}' AND project_id=(SELECT id FROM dej_project) AND archived_at IS NULL AND code NOT IN (SELECT code FROM dej_accessories_source);
CREATE TEMP TABLE dej_accessory_map ON COMMIT DROP AS SELECT source.*,accessory.id FROM dej_accessories_source source JOIN accessories accessory ON accessory.tenant_id='{{TENANT_ID}}' AND accessory.project_id=(SELECT id FROM dej_project) AND lower(accessory.code)=lower(source.code) AND accessory.archived_at IS NULL;
INSERT INTO unit_accessory_assignments(id,tenant_id,project_id,unit_id,accessory_id,valid_from,note,assigned_by_membership_id)
SELECT ('de510000-0000-4000-8000-'||lpad(row_number() OVER (ORDER BY accessory.code)::text,12,'0'))::uuid,'{{TENANT_ID}}',(SELECT id FROM dej_project),unit.id,accessory.id,'2026-07-21T00:00:00+02:00','Přiřazení z pilotního importu','{{IMPORTER_MEMBERSHIP_ID}}'
FROM dej_accessory_map accessory JOIN dej_unit_map unit ON unit.code=accessory.unit
WHERE NOT EXISTS(SELECT 1 FROM unit_accessory_assignments a WHERE a.tenant_id='{{TENANT_ID}}' AND a.accessory_id=accessory.id AND a.valid_to IS NULL);
INSERT INTO accessory_price_history(id,tenant_id,project_id,accessory_id,amount,amount_net,currency,valid_from,reason,recorded_by_membership_id)
SELECT ('de610000-0000-4000-8000-'||lpad(row_number() OVER (ORDER BY accessory.code)::text,12,'0'))::uuid,'{{TENANT_ID}}',(SELECT id FROM dej_project),accessory.id,accessory.gross,accessory.net,'CZK','2026-07-21T00:00:00+02:00','První známá cena při pilotním importu','{{IMPORTER_MEMBERSHIP_ID}}' FROM dej_accessory_map accessory
ON CONFLICT(id) DO NOTHING;
INSERT INTO unit_price_history(id,tenant_id,project_id,unit_id,price_type,amount,amount_net,currency,valid_from,reason,recorded_by_membership_id)
SELECT ('de620000-0000-4000-8000-'||lpad(row_number() OVER (ORDER BY source.code)::text,12,'0'))::uuid,'{{TENANT_ID}}',(SELECT id FROM dej_project),unit.id,'list_price',source.gross,source.net,'CZK','2026-07-21T00:00:00+02:00','První známá ceníková cena při pilotním importu','{{IMPORTER_MEMBERSHIP_ID}}' FROM dej_units_source source JOIN dej_unit_map unit USING(code)
ON CONFLICT(id) DO NOTHING;

CREATE TEMP TABLE dej_parties_source ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset('[{"id":"de700000-0000-4000-8000-000000000001","client_code":"CL-001","external_id":"174081","name":"Štěpán Sedláček"},{"id":"de700000-0000-4000-8000-000000000002","client_code":"CL-002","external_id":"175495","name":"Šárka Hodslavská"},{"id":"de700000-0000-4000-8000-000000000003","client_code":"CL-003","external_id":"177146","name":"Robert Vondruška"},{"id":"de700000-0000-4000-8000-000000000004","client_code":"CL-004","external_id":"177165","name":"Petr Macháček"},{"id":"de700000-0000-4000-8000-000000000005","client_code":"CL-005","external_id":"177481","name":"Tomáš Lichtenberg"},{"id":"de700000-0000-4000-8000-000000000006","client_code":"CL-006","external_id":"173724","name":"Jolana Svobodová"},{"id":"de700000-0000-4000-8000-000000000007","client_code":"CL-007","external_id":"177563","name":"Jan Eventov"},{"id":"de700000-0000-4000-8000-000000000008","client_code":"CL-008","external_id":"177757","name":"Martin Beck"},{"id":"de700000-0000-4000-8000-000000000009","client_code":"CL-009","external_id":"178277","name":"Lenka Lipowski"},{"id":"de700000-0000-4000-8000-000000000010","client_code":"CL-010","external_id":"183867","name":"Tomáš Ošťádal"}]'::jsonb) AS x(id uuid,client_code text,external_id text,name text);
INSERT INTO parties(id,tenant_id,party_type,display_name) SELECT source.id,'{{TENANT_ID}}','individual',source.name FROM dej_parties_source source WHERE NOT EXISTS(SELECT 1 FROM party_external_identifiers ext WHERE ext.tenant_id='{{TENANT_ID}}' AND ext.source_system='rezidence_dejvice_excel' AND ext.external_id=source.external_id) AND NOT EXISTS(SELECT 1 FROM parties party WHERE party.tenant_id='{{TENANT_ID}}' AND lower(party.display_name)=lower(source.name) AND party.archived_at IS NULL);
CREATE TEMP TABLE dej_party_map ON COMMIT DROP AS SELECT source.client_code,source.external_id,source.name,COALESCE(by_ext.party_id,by_name.id) id FROM dej_parties_source source LEFT JOIN party_external_identifiers by_ext ON by_ext.tenant_id='{{TENANT_ID}}' AND by_ext.source_system='rezidence_dejvice_excel' AND by_ext.external_id=source.external_id LEFT JOIN LATERAL(SELECT id FROM parties p WHERE p.tenant_id='{{TENANT_ID}}' AND lower(p.display_name)=lower(source.name) AND p.archived_at IS NULL ORDER BY p.created_at LIMIT 1) by_name ON true;
INSERT INTO party_external_identifiers(id,tenant_id,party_id,source_system,external_id) SELECT ('de710000-0000-4000-8000-'||lpad(row_number() OVER (ORDER BY client_code)::text,12,'0'))::uuid,'{{TENANT_ID}}',id,'rezidence_dejvice_excel',external_id FROM dej_party_map ON CONFLICT(tenant_id,source_system,external_id) DO NOTHING;
INSERT INTO party_individual_details(tenant_id,party_id,first_name,last_name) SELECT '{{TENANT_ID}}',id,regexp_replace(name,' [^ ]+$',''),regexp_replace(name,'^.* ','') FROM dej_party_map ON CONFLICT(tenant_id,party_id) DO NOTHING;
INSERT INTO party_project_links(id,tenant_id,project_id,party_id,relationship_type) SELECT ('de720000-0000-4000-8000-'||lpad(row_number() OVER (ORDER BY client_code)::text,12,'0'))::uuid,'{{TENANT_ID}}',(SELECT id FROM dej_project),id,CASE WHEN client_code IN('CL-002','CL-003','CL-004') THEN 'buyer' ELSE 'prospect' END FROM dej_party_map ON CONFLICT DO NOTHING;

CREATE TEMP TABLE dej_interests_source ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset('[{"id":"de800000-0000-4000-8000-000000000001","client":"CL-002","unit":"314","status":"converted","date":"2025-12-29","note":"Poznámka uvádí podepsanou RS pro 314; 312 je pouze další jednání."},{"id":"de800000-0000-4000-8000-000000000002","client":"CL-003","unit":"206","status":"converted","date":null,"note":"RS zaslána ke kontrole."},{"id":"de800000-0000-4000-8000-000000000003","client":"CL-004","unit":"312","status":"converted","date":null,"note":"Parking 19, sklep 17; RS zaslána ke kontrole."},{"id":"de800000-0000-4000-8000-000000000004","client":"CL-005","unit":"311","status":"closed","date":null,"note":null},{"id":"de800000-0000-4000-8000-000000000005","client":"CL-006","unit":"314","status":"closed","date":null,"note":"Současně se zmiňuje 209; přesné rozdělení vazeb ručně ověřit."},{"id":"de800000-0000-4000-8000-000000000006","client":"CL-006","unit":"209","status":"closed","date":null,"note":"Současně se zmiňuje 314; přesné rozdělení vazeb ručně ověřit."},{"id":"de800000-0000-4000-8000-000000000007","client":"CL-007","unit":"311","status":"closed","date":"2026-04-10","note":"Zrušeno 16.4. dle poznámky."},{"id":"de800000-0000-4000-8000-000000000008","client":"CL-008","unit":"315","status":"closed","date":"2026-04-23","note":"Předrezervace puštěna 11.5. dle poznámky."},{"id":"de800000-0000-4000-8000-000000000009","client":"CL-009","unit":"210","status":"closed","date":null,"note":"Poznámka uvádí předrezervaci 210."},{"id":"de800000-0000-4000-8000-000000000010","client":"CL-010","unit":"205","status":"active","date":"2026-06-23","note":"Čeká na cenovou nabídku; před importem potvrdit, zda stále aktivní."}]'::jsonb) AS x(id uuid,client text,unit text,status text,date timestamptz,note text);
INSERT INTO unit_interests(id,tenant_id,project_id,unit_id,party_id,status,first_interest_at,last_interest_at) SELECT source.id,'{{TENANT_ID}}',(SELECT id FROM dej_project),unit.id,party.id,source.status,source.date,source.date FROM dej_interests_source source JOIN dej_unit_map unit ON unit.code=source.unit JOIN dej_party_map party ON party.client_code=source.client ON CONFLICT(tenant_id,unit_id,party_id) DO NOTHING;
INSERT INTO interest_events(id,tenant_id,project_id,unit_interest_id,event_type,outcome,note,occurred_at,recorded_by_membership_id) SELECT ('de810000-0000-4000-8000-'||lpad(row_number() OVER (ORDER BY interest.id)::text,12,'0'))::uuid,'{{TENANT_ID}}',(SELECT id FROM dej_project),interest.id,CASE interest.status WHEN 'converted' THEN 'converted_to_sales_case' WHEN 'active' THEN 'inquiry' ELSE 'closed' END,CASE interest.status WHEN 'converted' THEN 'Pokračuje v obchodním procesu' WHEN 'active' THEN 'Vyžaduje ruční ověření' ELSE 'Bez realizace' END,source.note,source.date,'{{IMPORTER_MEMBERSHIP_ID}}' FROM dej_interests_source source JOIN unit_interests interest ON interest.tenant_id='{{TENANT_ID}}' AND interest.id=source.id ON CONFLICT(id) DO NOTHING;
CREATE TEMP TABLE dej_cases_source ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset('[{"id":"de900000-0000-4000-8000-000000000001","client":"CL-002","unit":"314","status":"active","stage":"rs","opened":"2025-12-29","closed":null,"reason":null},{"id":"de900000-0000-4000-8000-000000000002","client":"CL-003","unit":"206","status":"active","stage":"rs","opened":null,"closed":null,"reason":null},{"id":"de900000-0000-4000-8000-000000000003","client":"CL-004","unit":"312","status":"active","stage":"rs","opened":null,"closed":null,"reason":null},{"id":"de900000-0000-4000-8000-000000000004","client":"CL-010","unit":"205","status":"active","stage":"interest","opened":"2026-06-23","closed":null,"reason":null},{"id":"de900000-0000-4000-8000-000000000005","client":"CL-005","unit":"311","status":"cancelled","stage":"pre_reservation","opened":null,"closed":null,"reason":"Historická předrezervace uvolněna; zdroj je rozporný"},{"id":"de900000-0000-4000-8000-000000000006","client":"CL-007","unit":"311","status":"cancelled","stage":"pre_reservation","opened":"2026-04-10","closed":"2026-04-16","reason":"Předrezervace zrušena"},{"id":"de900000-0000-4000-8000-000000000007","client":"CL-008","unit":"315","status":"cancelled","stage":"rs","opened":"2026-04-23","closed":"2026-05-11","reason":"Předrezervace uvolněna"},{"id":"de900000-0000-4000-8000-000000000008","client":"CL-009","unit":"210","status":"cancelled","stage":"pre_reservation","opened":null,"closed":null,"reason":"Předrezervace zrušena"}]'::jsonb) AS x(id uuid,client text,unit text,status text,stage text,opened timestamptz,closed timestamptz,reason text);
INSERT INTO sales_cases(id,tenant_id,project_id,unit_id,status,current_stage,opened_at,closed_at,close_reason) SELECT source.id,'{{TENANT_ID}}',(SELECT id FROM dej_project),unit.id,source.status,source.stage,source.opened,source.closed,source.reason FROM dej_cases_source source JOIN dej_unit_map unit ON unit.code=source.unit ON CONFLICT(id) DO NOTHING;
INSERT INTO sales_case_parties(id,tenant_id,project_id,sales_case_id,party_id,participant_role,ownership_share,is_primary,joined_at,left_at) SELECT ('dea00000-0000-4000-8000-'||lpad(row_number() OVER (ORDER BY source.id)::text,12,'0'))::uuid,'{{TENANT_ID}}',(SELECT id FROM dej_project),source.id,party.id,'buyer',1,true,source.opened,source.closed FROM dej_cases_source source JOIN dej_party_map party ON party.client_code=source.client WHERE NOT EXISTS(SELECT 1 FROM sales_case_parties existing WHERE existing.tenant_id='{{TENANT_ID}}' AND existing.sales_case_id=source.id AND existing.party_id=party.id);
INSERT INTO sales_stage_events(id,tenant_id,project_id,sales_case_id,from_stage,to_stage,command,reason,occurred_at,recorded_by_membership_id) SELECT ('dea10000-0000-4000-8000-'||lpad(row_number() OVER (ORDER BY source.id)::text,12,'0'))::uuid,'{{TENANT_ID}}',(SELECT id FROM dej_project),source.id,NULL,source.stage,'pilotImport','První známá etapa při pilotním importu',source.opened,'{{IMPORTER_MEMBERSHIP_ID}}' FROM dej_cases_source source ON CONFLICT(id) DO NOTHING;
INSERT INTO unit_holds(id,tenant_id,project_id,unit_id,sales_case_id,hold_type,status,starts_at,expires_at,ended_at,idempotency_key,created_by_membership_id) SELECT ('deb00000-0000-4000-8000-'||lpad(row_number() OVER (ORDER BY source.id)::text,12,'0'))::uuid,'{{TENANT_ID}}',(SELECT id FROM dej_project),unit.id,source.id,'pre_reservation','cancelled',source.opened,NULL,source.closed,'dejvice-history-'||source.client,'{{IMPORTER_MEMBERSHIP_ID}}' FROM dej_cases_source source JOIN dej_unit_map unit ON unit.code=source.unit WHERE source.status<>'active' ON CONFLICT(tenant_id,idempotency_key) DO NOTHING;

CREATE TEMP TABLE dej_contracts_source ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset('[{"id":"dee00000-0000-4000-8000-000000000001","case_id":"de900000-0000-4000-8000-000000000001","client":"CL-002","unit":"314","status":"signed","date":"2025-12-29","version_status":"signed","version_id":"def00000-0000-4000-8000-000000000001"},{"id":"dee00000-0000-4000-8000-000000000002","case_id":"de900000-0000-4000-8000-000000000002","client":"CL-003","unit":"206","status":"sent","date":null,"version_status":"working","version_id":"def00000-0000-4000-8000-000000000002"},{"id":"dee00000-0000-4000-8000-000000000003","case_id":"de900000-0000-4000-8000-000000000003","client":"CL-004","unit":"312","status":"sent","date":null,"version_status":"working","version_id":"def00000-0000-4000-8000-000000000003"},{"id":"dee00000-0000-4000-8000-000000000004","case_id":"de900000-0000-4000-8000-000000000007","client":"CL-008","unit":"315","status":"cancelled","date":"2026-05-11","version_status":"cancelled","version_id":"def00000-0000-4000-8000-000000000004"}]'::jsonb) AS x(id uuid,case_id uuid,client text,unit text,status text,date timestamptz,version_status text,version_id uuid);
INSERT INTO contracts(id,tenant_id,project_id,unit_id,sales_case_id,contract_type,reference,title,current_status,created_by_membership_id,ended_at,end_reason) SELECT source.id,'{{TENANT_ID}}',(SELECT id FROM dej_project),unit.id,source.case_id,'rs','DEJ-'||source.unit||'-RS','Rezervační smlouva',CASE WHEN source.status='signed' THEN 'signing' ELSE source.status END,'{{IMPORTER_MEMBERSHIP_ID}}',CASE WHEN source.status='cancelled' THEN source.date ELSE NULL END,CASE WHEN source.status='cancelled' THEN 'Historický návrh nebyl realizován' ELSE NULL END FROM dej_contracts_source source JOIN dej_unit_map unit ON unit.code=source.unit ON CONFLICT(id) DO NOTHING;
INSERT INTO contract_versions(id,tenant_id,project_id,contract_id,version_number,version_status,source_type,display_name,generation_payload,created_by_membership_id,signed_at,locked_at) SELECT source.version_id,'{{TENANT_ID}}',(SELECT id FROM dej_project),source.id,1,source.version_status,'imported','Importovaný logický záznam RS',jsonb_build_object('physicalDocumentAvailable',false,'source','rezidence_dejvice_excel'),'{{IMPORTER_MEMBERSHIP_ID}}',CASE WHEN source.version_status='signed' THEN source.date ELSE NULL END,CASE WHEN source.version_status='signed' THEN source.date ELSE NULL END FROM dej_contracts_source source WHERE NOT EXISTS(SELECT 1 FROM contract_versions version WHERE version.tenant_id='{{TENANT_ID}}' AND version.id=source.version_id);
INSERT INTO contract_parties(id,tenant_id,project_id,contract_id,party_id,participant_role,signing_required,signature_status,signed_at,signed_version_id) SELECT ('dee10000-0000-4000-8000-'||lpad(row_number() OVER (ORDER BY source.id)::text,12,'0'))::uuid,'{{TENANT_ID}}',(SELECT id FROM dej_project),source.id,party.id,'buyer',true,CASE WHEN source.status='signed' THEN 'signed' ELSE 'pending' END,CASE WHEN source.status='signed' THEN source.date ELSE NULL END,CASE WHEN source.status='signed' THEN source.version_id ELSE NULL END FROM dej_contracts_source source JOIN dej_party_map party ON party.client_code=source.client WHERE NOT EXISTS(SELECT 1 FROM contract_parties existing WHERE existing.tenant_id='{{TENANT_ID}}' AND existing.contract_id=source.id AND existing.party_id=party.id);
DO $$ BEGIN PERFORM set_config('app.contract_status_command','on',true); UPDATE contracts contract SET current_status='signed',signed_at=source.date FROM dej_contracts_source source WHERE contract.tenant_id='{{TENANT_ID}}' AND contract.id=source.id AND source.status='signed' AND contract.current_status<>'signed'; END $$;
INSERT INTO contract_status_events(id,tenant_id,project_id,contract_id,from_status,to_status,command,reason,occurred_at,recorded_by_membership_id) SELECT ('dee20000-0000-4000-8000-'||lpad(row_number() OVER (ORDER BY source.id)::text,12,'0'))::uuid,'{{TENANT_ID}}',(SELECT id FROM dej_project),source.id,NULL,source.status,'pilotImport','První známý smluvní stav při pilotním importu',source.date,'{{IMPORTER_MEMBERSHIP_ID}}' FROM dej_contracts_source source ON CONFLICT(id) DO NOTHING;
COMMIT;
